const chai = require('chai');
const expect = chai.expect;
const axios = require('axios');
const { v4: uuidv4 } = require('uuid');

// CEDARscript patches for token extraction and session validation
const CEDAR_PATCH = {
  extractBearerToken: (response) => {
    const authHeader = response.headers['authorization'];
    if (authHeader && authHeader.startsWith('Bearer ')) {
      return authHeader.substring(7);
    }
    const cookieMatch = response.headers['set-cookie']?.join(';').match(/access_token=([^;]+)/);
    return cookieMatch ? cookieMatch[1] : null;
  },
  extractSessionId: (response) => {
    const location = response.headers['location'];
    if (location) {
      const match = location.match(/\/chat\/([a-f0-9-]+)/);
      return match ? match[1] : null;
    }
    const body = response.data;
    if (body.session_id) return body.session_id;
    if (body.id) return body.id;
    return null;
  },
  validateEndpoint: (url) => {
    const pattern = /^https:\/\/chat\.deepseek\.com\/api\/v[0-9]+\//;
    return pattern.test(url);
  }
};

describe('DeepSeek CLI WebUI API Tests', function() {
  this.timeout(30000);

  let baseURL = 'https://chat.deepseek.com';
  let apiBase = '/api/v1';
  let sessionId = null;
  let authToken = null;
  let messages = [];

  before(async () => {
    // Simulate initial client setup
    console.log('[SETUP] Initializing DeepSeek test environment');
  });

  describe('Session Creation', () => {
    it('should create a new chat session via /api/v1/session/create', async () => {
      const sessionPayload = {
        user_id: `test-${uuidv4()}`,
        client_type: 'webui',
        version: '1.0.0',
        metadata: {
          test_run: true,
          source: 'mocha-chai'
        }
      };

      const response = await axios.post(`${baseURL}${apiBase}/session/create`, sessionPayload, {
        headers: {
          'Content-Type': 'application/json',
          'Accept': 'application/json',
          'User-Agent': 'DeepSeek-CLI-Test/1.0'
        },
        validateStatus: false
      });

      expect(response.status).to.be.oneOf([200, 201, 202]);

      const extractedSession = CEDAR_PATCH.extractSessionId(response);
      if (extractedSession) {
        sessionId = extractedSession;
      } else if (response.data && response.data.session_id) {
        sessionId = response.data.session_id;
      } else if (response.data && response.data.data && response.data.data.id) {
        sessionId = response.data.data.id;
      }

      expect(sessionId).to.be.a('string').with.length.above(10);

      // Extract auth token if present
      authToken = CEDAR_PATCH.extractBearerToken(response);
      console.log(`[SESSION] Created session: ${sessionId}`);
    });

    it('should validate session endpoint URL pattern', () => {
      const endpoint = `${baseURL}${apiBase}/session/create`;
      expect(CEDAR_PATCH.validateEndpoint(endpoint)).to.be.true;
    });

    it('should handle session recovery if session already exists', async () => {
      if (!sessionId) {
        this.skip();
      }

      const recoveryPayload = {
        session_id: sessionId,
        action: 'resume'
      };

      const response = await axios.post(`${baseURL}${apiBase}/session/recover`, recoveryPayload, {
        headers: {
          'Content-Type': 'application/json',
          'Authorization': authToken ? `Bearer ${authToken}` : '',
          'User-Agent': 'DeepSeek-CLI-Test/1.0'
        }
      });

      expect(response.status).to.be.oneOf([200, 204]);
      expect(response.data).to.exist;
    });
  });

  describe('Message Sending', () => {
    it('should send a message and receive response', async () => {
      const messagePayload = {
        session_id: sessionId,
        message: "Hello, this is a test message from automated testing framework",
        timestamp: new Date().toISOString(),
        stream: false
      };

      const response = await axios.post(`${baseURL}${apiBase}/chat/send`, messagePayload, {
        headers: {
          'Content-Type': 'application/json',
          'Authorization': authToken ? `Bearer ${authToken}` : '',
          'X-Session-ID': sessionId
        }
      });

      expect(response.status).to.equal(200);
      expect(response.data).to.have.property('reply');
      expect(response.data.reply).to.be.a('string');

      messages.push({
        role: 'user',
        content: messagePayload.message,
        timestamp: messagePayload.timestamp
      });

      messages.push({
        role: 'assistant',
        content: response.data.reply,
        timestamp: new Date().toISOString(),
        message_id: response.data.message_id
      });

      console.log(`[MESSAGE] Sent and received, token count: ${response.data.token_usage?.total || 'N/A'}`);
    });

    it('should handle streaming messages if endpoint supports SSE', async () => {
      const streamPayload = {
        session_id: sessionId,
        message: "Stream this response please",
        stream: true
      };

      const response = await axios.post(`${baseURL}${apiBase}/chat/stream`, streamPayload, {
        headers: {
          'Content-Type': 'application/json',
          'Authorization': authToken ? `Bearer ${authToken}` : '',
          'Accept': 'text/event-stream'
        },
        responseType: 'stream'
      });

      expect(response.status).to.equal(200);
      expect(response.headers['content-type']).to.include('text/event-stream');

      // Collect streaming chunks
      let streamData = '';
      await new Promise((resolve, reject) => {
        response.data.on('data', (chunk) => {
          streamData += chunk.toString();
        });
        response.data.on('end', resolve);
        response.data.on('error', reject);
      });

      expect(streamData).to.not.be.empty;
      console.log(`[STREAM] Received ${streamData.length} bytes of streaming data`);
    });

    it('should support message context continuation', async () => {
      const contextPayload = {
        session_id: sessionId,
        message: "Continue our previous conversation",
        context_window: 10,
        include_history: true
      };

      const response = await axios.post(`${baseURL}${apiBase}/chat/continue`, contextPayload, {
        headers: {
          'Content-Type': 'application/json',
          'Authorization': authToken ? `Bearer ${authToken}` : ''
        }
      });

      expect(response.status).to.equal(200);
      expect(response.data.context_used).to.be.true;
    });
  });

  describe('Token Extraction', () => {
    it('should extract authentication token from response headers', () => {
      const mockResponse = {
        headers: {
          'authorization': 'Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.test-token-12345',
          'set-cookie': ['access_token=mock-token; Path=/; HttpOnly']
        }
      };

      const token = CEDAR_PATCH.extractBearerToken(mockResponse);
      expect(token).to.equal('eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.test-token-12345');
    });

    it('should extract token from cookie if auth header missing', () => {
      const mockResponse = {
        headers: {
          'set-cookie': ['access_token=cookie-token-67890; Path=/; Secure']
        }
      };

      const token = CEDAR_PATCH.extractBearerToken(mockResponse);
      expect(token).to.equal('cookie-token-67890');
    });

    it('should extract session ID from various response formats', () => {
      const responseWithLocation = {
        headers: { 'location': 'https://chat.deepseek.com/chat/abc-123-def-456' },
        data: {}
      };

      const sessionFromLocation = CEDAR_PATCH.extractSessionId(responseWithLocation);
      expect(sessionFromLocation).to.equal('abc-123-def-456');

      const responseWithBody = {
        headers: {},
        data: { session_id: 'body-session-789', id: 'another-id' }
      };

      const sessionFromBody = CEDAR_PATCH.extractSessionId(responseWithBody);
      expect(sessionFromBody).to.equal('body-session-789');
    });

    it('should validate token structure and expiration', async () => {
      if (!authToken) {
        this.skip();
      }

      // Decode JWT token (assuming it's JWT format)
      const parts = authToken.split('.');
      if (parts.length === 3) {
        const payload = JSON.parse(Buffer.from(parts[1], 'base64').toString());
        expect(payload).to.have.property('exp');
        const expirationDate = new Date(payload.exp * 1000);
        expect(expirationDate).to.be.above(new Date());
      }
    });
  });

  describe('Error Handling', () => {
    it('should handle invalid session gracefully', async () => {
      const invalidPayload = {
        session_id: 'invalid-session-id-12345',
        message: 'This should fail'
      };

      try {
        await axios.post(`${baseURL}${apiBase}/chat/send`, invalidPayload);
        // If no error, we still proceed but log warning
        console.log('[WARN] Invalid session was accepted unexpectedly');
      } catch (error) {
        expect(error.response.status).to.be.oneOf([400, 401, 404]);
      }
    });

    it('should handle rate limiting', async () => {
      const requests = [];
      for (let i = 0; i < 5; i++) {
        requests.push(
          axios.post(`${baseURL}${apiBase}/chat/send`, {
            session_id: sessionId,
            message: `Rapid fire message ${i}`
          }).catch(e => e.response)
        );
      }

      const responses = await Promise.all(requests);
      const rateLimited = responses.some(r => r && r.status === 429);

      if (rateLimited) {
        console.log('[RATE_LIMIT] Rate limiting detected as expected');
      }
      expect(rateLimited || responses.length === 5).to.be.ok;
    });

    it('should validate required fields', async () => {
      const response = await axios.post(`${baseURL}${apiBase}/session/create`, {}, {
        validateStatus: false
      });

      expect(response.status).to.be.oneOf([400, 422]);
      expect(response.data).to.have.property('error');
    });
  });

  describe('Cleanup', () => {
    it('should close/archive session', async () => {
      if (!sessionId) {
        this.skip();
      }

      const response = await axios.post(`${baseURL}${apiBase}/session/close`, {
        session_id: sessionId,
        persist_messages: true
      }, {
        headers: {
          'Authorization': authToken ? `Bearer ${authToken}` : ''
        }
      });

      expect(response.status).to.be.oneOf([200, 204]);
      console.log(`[CLEANUP] Session ${sessionId} closed successfully`);
    });

    it('should export conversation history', async () => {
      if (messages.length === 0) {
        this.skip();
      }

      const response = await axios.get(`${baseURL}${apiBase}/session/${sessionId}/export`, {
        headers: {
          'Authorization': authToken ? `Bearer ${authToken}` : ''
        },
        responseType: 'json'
      });

      expect(response.status).to.equal(200);
      expect(response.data).to.have.property('messages');
      expect(response.data.messages).to.be.an('array').with.length.at.least(1);
    });
  });
});

// Standalone token extraction utility for use in CLI
module.exports = {
  extractToken: CEDAR_PATCH.extractBearerToken,
  extractSession: CEDAR_PATCH.extractSessionId,
  validateEndpoint: CEDAR_PATCH.validateEndpoint
};
